-- Biography provenance and review flags (12 Oct 2026).
--  * bio_sources          named sources behind the written biography: [{title, url, supports}]
--  * bio_last_reviewed    date the biography was last fully fact-checked (shown as "Last reviewed")
--  * bio_review_reason    set by the nightly syncs when a change means the biography should be rechecked
--  * bio_review_flagged_at  when that flag was last raised
--  * bio_visible          whether the biography is shown on the profile (replaces the code list
--                         BIO_VISIBLE_MEMBER_IDS in app/mps/[id]/MagazineProfileSections.tsx)
-- Existing biography text is not changed. Re-runnable.
\set ON_ERROR_STOP on
BEGIN;
ALTER TABLE public.mp_biography
  ADD COLUMN IF NOT EXISTS bio_sources jsonb,
  ADD COLUMN IF NOT EXISTS bio_last_reviewed date,
  ADD COLUMN IF NOT EXISTS bio_review_reason text,
  ADD COLUMN IF NOT EXISTS bio_review_flagged_at timestamptz,
  ADD COLUMN IF NOT EXISTS bio_visible boolean NOT NULL DEFAULT false;

