   SET bio_sources = $j$[{"title": "Camden: Holborn and St Pancras by-election 2026 results", "url": "https://www.camden.gov.uk/holborn-and-st-pancras-by-election-2026-results", "supports": "By-election votes, rejected ballots and 38.76 per cent turnout"}, {"title": "UK Parliament: Holborn and St Pancras 2024 general election result", "url": "https://members.parliament.uk/constituency/4105/election/422", "supports": "2024 majority of 11,572 and turnout of 54.1 per cent"}, {"title": "Camden: May 2026 local election results, Camden Square ward", "url": "https://www.camden.gov.uk/local-election-may-2026-results-camden-square-ward", "supports": "Ward votes of 890, 848 and 830"}, {"title": "Camden New Journal: Labour inch over the line to hold Camden but lose leader", "url": "https://www.camdennewjournal.co.uk/article/labour-inch-over-the-line-to-hold-camden-council-but-lose-leader", "supports": "Greens from one seat to 11; previous leader lost his seat"}, {"title": "Fitzrovia News: Labour choose Sagal Abdi-Wali as new Camden leader", "url": "https://fitzrovianews.com/2026/05/17/labour-choose-sagal-abdi-wali-as-new-camden-leader/", "supports": "Labour on 30 of 55 seats after losing 17; councillor for Camden Square since 2022"}, {"title": "Camden Council: New leader and cabinet announced", "url": "https://news.camden.gov.uk/new-leader-and-cabinet-announced/", "supports": "Leader from 20 May 2026, first Black woman leader, priorities, Euston and HS2 role"}, {"title": "Camden Council: Cllr Sagal Abdi-Wali is new housing lead", "url": "https://news.camden.gov.uk/cllr-sagal-abdi-wali-is-new-housing-lead/", "supports": "Better Homes portfolio from May 2024, its responsibilities, housing department background"}, {"title": "Camden New Journal: Sagal Abdi-Wali selected as Labour candidate", "url": "https://www.camdennewjournal.co.uk/article/how-it-happened-sagal-abdi-wali-is-selected-as-labour-candidate-in-holborn-and-st-pancras", "supports": "Arrived as a child refugee from Somalia"}, {"title": "Camden New Journal: profile of Camden's new leader", "url": "https://www.camdennewjournal.co.uk/article/camdens-new-leader-views-from-the-heath-are-important-but-people-need-somewhere-to-call-a-home", "supports": "Walthamstow then Gospel Oak; community projects"}, {"title": "Camden New Journal, August 2019: candidates in Labour selection", "url": "https://www.camdennewjournal.co.uk/article/race-for-city-hall-candidates-in-labour-selection-showdown", "supports": "Chair of Holborn and St Pancras CLP in 2019"}, {"title": "LabourList: Sagal Abdi-Wali, Labour candidate in Holborn and St Pancras", "url": "https://labourlist.org/2026/09/sagal-abdi-wali-labour-candidate-in-the-holborn-and-st-pancras-by-election/", "supports": "School governor, in her own description"}, {"title": "ITV News: Abdi-Wali says by-election victory is testament to diversity", "url": "https://www.itv.com/news/2026-10-09/sagal-abdi-wali-says-labour-byelection-victory-is-testament-to-diversity", "supports": "Priorities, community cohesion and Thames Water public ownership"}, {"title": "Camden Cabinet decision: Housing Investment Strategy, 15 January 2025", "url": "https://camden.moderngov.co.uk/ieDecisionDetails.aspx?ID=4563", "supports": "Additional £350 million, including up to £265 million from asset management"}, {"title": "Camden Council press release, 16 January 2025", "url": "https://news.camden.gov.uk/camden-drives-forward-work-to-build-thousands-of-more-homes-and-improve-quality-of-housing/", "supports": "280 and 307 homes, 100 families, 8,000 on the waiting list"}, {"title": "Camden Housing Investment Strategy 2025 to 2030", "url": "https://www.camden.gov.uk/documents/d/guest/housing-investment-strategy-2025-to-2030", "supports": "£670 million plan, £300 million gap, buy-backs at no net cost"}, {"title": "Housing Ombudsman special investigation into Camden, November 2024", "url": "https://housing-ombudsman.org.uk/app/uploads/2024/11/Camden-P49-Report-November-2024.pdf", "supports": "Began November 2023; 91 per cent against 73 per cent; findings"}, {"title": "Camden decision: Approval of the Repairs Policy, 2 March 2026", "url": "https://camden.moderngov.co.uk/ieDecisionDetails.aspx?ID=5143", "supports": "24-hour emergency standard; consolidates existing practice"}, {"title": "Camden Council: Tenant satisfaction measures 2024 to 2025", "url": "https://www.camden.gov.uk/tenant-satisfaction-measures-2024-to-2025", "supports": "2024/25 performance figures and London medians"}, {"title": "Camden Council: 2026/27 housing budget agreed", "url": "https://news.camden.gov.uk/cabinet-agrees-202627-housing-budget-with-focus-on-better-quality-homes-for-residents/", "supports": "4.8 per cent rent rise, £8.1 million to £10.4 million, £1 million service charges, 72 per cent, £3 million for Awaab's Law"}]$j$::jsonb,
